<?php namespace App\Jobs; use App\Models\Booking; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Mail; use RuntimeException; use Throwable; class SendTicketEmailJob implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public int $tries=5; public array $backoff=[10,30,90,300,600]; public int $timeout=60; public function __construct(public int $bookingId){} public function handle():void{$b=Booking::with(['user','tickets'])->findOrFail($this->bookingId);if($b->status->value!=='paid')return;if(config('services.mail.fail'))throw new RuntimeException('محاكاة تعطل مزود البريد');$key='ticket-email-'.$b->id;cache()->lock('lock:'.$key,120)->block(10,function()use($b,$key){if(cache()->has('sent:'.$key))return;Mail::raw('تأكيد الحجز رقم '.$b->id.' - رموز التذاكر: '.$b->tickets->pluck('code')->join(', '),fn($m)=>$m->to($b->user->email)->subject('تذكرتي - تأكيد الشراء'));cache()->put('sent:'.$key,true,60*60*24*30);});} public function failed(?Throwable $e):void{logger()->critical('Ticket email permanently failed',['booking_id'=>$this->bookingId,'error'=>$e?->getMessage()]);}}
